      <Finanzierung
        amortisation={fmt(beispiel.kauf.amortisation, 0)}
        invest={fmtEur(Math.round(beispiel.invest.summe / 1000) * 1000)}
        preisCt={fmt(beispiel.contracting.preisCt, 1)}
        jahre={CARPORT.contractingJahre}
